//! The Lean declaration inventory: a machine-produced export of the facts L2R may
//! read from a Lean project.
//!
//! The inventory is generated by `tools/lean_inventory` from compiled Lean
//! modules. L2R never parses Lean source; it only resolves qualified names
//! against this inventory, so every reference is checked against what Lean
//! actually elaborated.

use serde::{Deserialize, Serialize};

/// The original inventory schema: constructors carry only their arity.
pub const INVENTORY_SCHEMA: &str = "l2r.lean-inventory/v0";

/// The inventory schema that also records, for every inductive type, whether
/// it is a structure, its parameters and indices, and the name and type of
/// every constructor field (`tools/lean_inventory/Main.lean --v1`). Required by
/// model schema `v2`, whose types may carry data.
pub const INVENTORY_SCHEMA_V1: &str = "l2r.lean-inventory/v1";

/// Exported declarations of one Lean project.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Inventory {
    /// Schema identifier: [`INVENTORY_SCHEMA`] or [`INVENTORY_SCHEMA_V1`].
    pub schema: String,
    /// Lean version that elaborated the declarations.
    pub lean_version: String,
    /// Root modules that were imported to produce the inventory.
    pub root_modules: Vec<String>,
    /// Exported declarations.
    pub declarations: Vec<Declaration>,
}

/// One exported Lean declaration.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Declaration {
    /// Fully qualified name.
    pub name: String,
    /// Declaration kind.
    pub kind: DeclKind,
    /// Type, pretty-printed with fully qualified names.
    #[serde(rename = "type")]
    pub type_: String,
    /// Constructors, for inductive types only.
    #[serde(default)]
    pub constructors: Vec<Constructor>,
    /// True when the inductive type is a Lean `structure` (inventory `v1`).
    #[serde(default, skip_serializing_if = "is_false")]
    pub structure: bool,
    /// Number of type parameters (inventory `v1`).
    #[serde(default, skip_serializing_if = "is_zero")]
    pub params: u32,
    /// Number of type indices (inventory `v1`).
    #[serde(default, skip_serializing_if = "is_zero")]
    pub indices: u32,
}

fn is_false(value: &bool) -> bool {
    !*value
}

fn is_zero(value: &u32) -> bool {
    *value == 0
}

/// Kinds of Lean declaration distinguished by L2R.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DeclKind {
    /// An inductive type.
    Inductive,
    /// A definition.
    Definition,
    /// A theorem.
    Theorem,
    /// An opaque constant.
    Opaque,
    /// An axiom.
    Axiom,
    /// Anything else (quotients, recursors, ...).
    Other,
}

/// A constructor of an inductive type.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Constructor {
    /// Fully qualified constructor name.
    pub name: String,
    /// Number of explicit and implicit fields, excluding type parameters.
    pub arity: u32,
    /// The fields, in order (inventory `v1`).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub fields: Vec<Field>,
}

/// One field of a constructor.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Field {
    /// The binder's name (a structure field's name).
    pub name: String,
    /// The field's type, pretty-printed with fully qualified names.
    #[serde(rename = "type")]
    pub type_: String,
}

impl Inventory {
    /// Returns the inventory in canonical form (declarations sorted by name).
    pub fn canonical(&self) -> Inventory {
        let mut inventory = self.clone();
        inventory.root_modules.sort();
        inventory.declarations.sort_by(|a, b| a.name.cmp(&b.name));
        inventory
    }

    /// Finds a declaration by its fully qualified name.
    pub fn find(&self, name: &str) -> Option<&Declaration> {
        self.declarations.iter().find(|d| d.name == name)
    }
}
